INSERT INTO `message` VALUES (18, 0, '1', '<p>今天是2024年7月12日，星期五，江山市的天气情况如下：\n\n- 当前天气：阴。\n- 湿度：55%。\n- 体感温度：38.0摄氏度。\n- 风向：西南风。\n- 风力：2级。\n\n明天的天气预报提到会有雨，会非常闷热，感觉像是在蒸桑拿。如果您需要更多详细信息或未来几天的天气预报，请告诉我。</p>', '2024-07-12 08:00:00', NULL);
