INSERT INTO `message` VALUES (22, 0, '1', '<p>你好！有什么问题或者需要我帮忙的吗？今天是2024年7月12日，星期五，宁波象山县的天气预报如下：\n\n- 白天天气：雷阵雨，东风，风力4级。\n- 夜间天气：雷阵雨，南风，风力5级。\n- 湿度为87%，最低温度27.0摄氏度，最高温度32.0摄氏度。\n- 体感温度可能会有所不同，且由于有雨，外出记得带伞，并注意防潮和安全。\n\n请根据实际情况调整你的行程和穿着。</p>', '2024-07-12 08:00:00', NULL);
