INSERT INTO `message` VALUES (26, 0, '1', '<p>2024年7月12日，星期五，宁波市的天气情况如下：\n\n- 当前天气：阴。\n- 湿度：88%。\n- 体感温度：31.0摄氏度。\n- 风向：西南风。\n- 风力：2级。\n\n虽然不是特别炎热，但由于湿度较高，可能会感觉比较闷热。记得保持水分，注意防暑哦。此外，有雷阵雨的预报，出门记得携带雨具。空气质量为优，空气质量指数为29，对户外活动非常适宜。</p>', '2024-07-12 08:00:00', NULL);
