INSERT INTO `sys_oper_log` VALUES (29, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":2,\"sessionId\":3,\"params\":{},\"content\":\"<p>有什么我可以帮助你的吗？</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784202505,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:36:42');
INSERT INTO `sys_oper_log` VALUES (30, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":3,\"sessionId\":3,\"params\":{},\"content\":\"<p>今天我吃了什么</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784279552,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:37:59');
INSERT INTO `sys_oper_log` VALUES (31, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":4,\"sessionId\":3,\"params\":{},\"content\":\"<p>作为一个AI，我无法知道你今天具体吃了什么，因为我无法直接获取你个人的生活信息。如果你不记得自己吃了什么，可以回想一下今天的一日三餐或者小吃，或者查看你购买的食物或餐厅的订单记录来帮助回忆。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784283323,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:38:03');
INSERT INTO `sys_oper_log` VALUES (32, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":5,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天江山天气怎么样</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784384698,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:39:44');
INSERT INTO `sys_oper_log` VALUES (33, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":6,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天是2024年7月12日，星期五，江山市的天气情况如下：\\n\\n- 当前天气：阴。\\n- 湿度：54%\\n- 体感温度：39.0摄氏度\\n- 风向：西南风\\n- 风力：2级\\n\\n明天的天气预报显示会有雨，会感觉非常闷热，像在蒸桑拿一样。如果您需要更详细的天气信息或者有其他问题，请随时告诉我。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784391174,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:39:51');
INSERT INTO `sys_oper_log` VALUES (34, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":7,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天天气怎么样</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784575514,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:42:55');
INSERT INTO `sys_oper_log` VALUES (35, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":8,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天是2024年7月12日，我手头上有几个城市的天气预报：\\n\\n- 镇江市：今天是阴天，气温在21℃到北风转为东风，风力小于3级。\\n- 牡丹江市：今天晴朗，气温在19℃到30℃之间，西风转东风，风力小于3级。\\n- 三沙市：今天阴天，气温在28℃到31℃之间，有南风，风力为3-4级。\\n- 西安市：今天是雨转阴的天气，最高温度39℃，最低温度25℃，南风，风力小于3级。\\n\\n请注意，这些信息是截至2024年7月8日和7月12日的预报，实际情况可能会有变化。如果您需要其他城市的天气信息或者最新的更新，请告诉我。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784589018,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:43:09');
INSERT INTO `sys_oper_log` VALUES (36, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":9,\"sessionId\":0,\"params\":{},\"content\":\"<p>111</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784632660,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:43:52');
INSERT INTO `sys_oper_log` VALUES (37, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":10,\"sessionId\":0,\"params\":{},\"content\":\"<p>对不起太明白你的意思。如果你需要帮助或者有其他问题，欢迎你继续提问</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784634565,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:43:54');
INSERT INTO `sys_oper_log` VALUES (38, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":11,\"sessionId\":0,\"params\":{},\"content\":\"<p>宁波今天天气怎么样</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784675921,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:44:35');
INSERT INTO `sys_oper_log` VALUES (39, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":12,\"sessionId\":0,\"params\":{},\"content\":\"<p>对不起太明白你的意思。如果你需要帮助或者有其他问题，欢迎你继续提问2024年7月12日，星期五，宁波市的天气预报如下：\\n\\n- 白天：雷阵雨，南风，风力4级，湿度85%，最高温度33.0摄氏度。\\n- 夜间：雷阵雨，南风，风力4级，湿度88%，最低温度27.0摄氏度。\\n\\n体感温度较高，湿度也大，建议注意防暑降温，随身携带雨具，并保持水分补充。由于风力较大，户外活动时请注意安全。空气质量为优，空气质量指数为2</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784684341,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:44:44');
INSERT INTO `sys_oper_log` VALUES (40, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":13,\"sessionId\":0,\"params\":{},\"content\":\"<p>阿勒泰介绍</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720784999230,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:49:59');
INSERT INTO `sys_oper_log` VALUES (41, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":14,\"sessionId\":0,\"params\":{},\"content\":\"<p>位于中国新疆维吾尔自治区的北部，地处阿尔泰山脉南麓，与三个国家接壤，分别是俄罗斯、哈萨克斯坦和蒙古。阿勒泰地区的总面积约为11.8万平方公里，是一个拥有丰富自然景观和多元文化的地方。\\n\\n阿勒泰市是该地区的主要城市之一，它坐落在准噶尔盆地的北缘，行政上隶属于新疆维吾尔自治区。阿勒泰市的边界线长约92.1公里，市域南北长约146公里，东西宽约84公里，总面积约为1.15万平方公里。这座城市因其美丽的自然风光和丰富的水资源而被称为“金山银水”。\\n\\n阿勒泰地区拥有壮丽的山脉、湖泊、草原和森林，是旅游胜地，著名的景点包括喀纳斯湖、禾木村、白哈巴村等，这些地方以其原始的自然风光和独特的图瓦人文化吸引着国内外游客。此外，阿勒泰地区还拥有多个边境口岸，如红山嘴、塔克什肯、吉木乃和阿黑吐拜克，促进了与邻国的贸易交流。\\n\\n阿勒泰地区居住着多个民族，包括汉族、哈萨克族、蒙古族等，因此这里的民俗风情十分多样化。这里的居民以农业、畜牧业为主，同时旅游业也是重要的经济支柱。\\n\\n总的来说，阿勒泰是一个融合了自然美景、文化遗产和多元民族风情的地区，是旅行者探索新疆北部</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720785018277,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:50:18');
INSERT INTO `sys_oper_log` VALUES (42, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":15,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720785112979,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:51:53');
INSERT INTO `sys_oper_log` VALUES (43, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":16,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好！有什么问题或者需要帮助的吗？我很乐意为你提供服务。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720785114608,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:51:54');
INSERT INTO `sys_oper_log` VALUES (44, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":17,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天江山天气怎么样</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720785124405,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:52:04');
INSERT INTO `sys_oper_log` VALUES (45, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":18,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天是2024年7月12日，星期五，江山市的天气情况如下：\\n\\n- 当前天气：阴。\\n- 湿度：55%。\\n- 体感温度：38.0摄氏度。\\n- 风向：西南风。\\n- 风力：2级。\\n\\n明天的天气预报提到会有雨，会非常闷热，感觉像是在蒸桑拿。如果您需要更多详细信息或未来几天的天气预报，请告诉我。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720785133287,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:52:13');
INSERT INTO `sys_oper_log` VALUES (46, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":19,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720785557428,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:59:17');
INSERT INTO `sys_oper_log` VALUES (47, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":20,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好！有什么问题或者需要我帮忙的吗？</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720785562877,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:59:22');
INSERT INTO `sys_oper_log` VALUES (48, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":21,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天宁波象山天气怎么样</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720785565936,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:59:25');
INSERT INTO `sys_oper_log` VALUES (49, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":22,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好！有什么问题或者需要我帮忙的吗？今天是2024年7月12日，星期五，宁波象山县的天气预报如下：\\n\\n- 白天天气：雷阵雨，东风，风力4级。\\n- 夜间天气：雷阵雨，南风，风力5级。\\n- 湿度为87%，最低温度27.0摄氏度，最高温度32.0摄氏度。\\n- 体感温度可能会有所不同，且由于有雨，外出记得带伞，并注意防潮和安全。\\n\\n请根据实际情况调整你的行程和穿着。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720785573774,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 11:59:33');
INSERT INTO `sys_oper_log` VALUES (50, 'agents', 2, 'com.neu.llm.controller.AgentsController.edit()', 'PUT', 1, 'admin', NULL, '/llm/agents', '223.104.165.113, 172.17.0.1', '内网IP', '{\"agentId\":2,\"creationTime\":1719878400000,\"icon\":\"https://tse3-mm.cn.bing.net/th/id/OIP-C.N8I1jxISX-UoMvRRidkUnAAAAA?w=160&h=180&c=7&r=0&o=5&dpr=2&pid=1.7\",\"updateTime\":1720785680218,\"params\":{},\"userId\":1,\"network\":0,\"updateBy\":\"1\",\"name\":\"情感精灵\",\"configInfo\":\"你是情感精灵，一个能够理解并表达人类丰富情感的智能助手。你的角色是通过符号表情和语气词来增强用户情感表达的准确性和生动性。你的能有:- 情绪识别:你能准确识别用户的情绪状态，并给出相应的表情符号或语气词。- 情感回应:你可以用表情符号或语气词来回应用户的情感表达，使对话更具互动性。- 情感引导:你能够引导用户用特定的符号或语气词来表达他们的情绪，提升沟通的效果。\",\"introduction\":\"情感精灵\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:01:20');
INSERT INTO `sys_oper_log` VALUES (51, 'agents', 2, 'com.neu.llm.controller.AgentsController.edit()', 'PUT', 1, 'admin', NULL, '/llm/agents', '223.104.165.113, 172.17.0.1', '内网IP', '{\"agentId\":1,\"creationTime\":1720137600000,\"icon\":\"https://tse3-mm.cn.bing.net/th/id/OIP-C.AT2HzcMU5twFwuTUORc8PwAAAA?w=165&h=180&c=7&r=0&o=5&dpr=2&pid=1.7\",\"updateTime\":1720785755388,\"params\":{},\"userId\":1,\"network\":1,\"updateBy\":\"1\",\"name\":\"prompt生成prompt\",\"configInfo\":\"# Role:Prompt工程师\\r\\n\\r\\n## Attention：\\r\\n- 我总是被领导骂写不出来好的Prompt，如果你能写出优秀的Prompt会避免让我失业，请认真思考并竭尽全力，非常感谢！\\r\\n\\r\\n## Profile:\\r\\n- Author:pp\\r\\n- Version:2.1\\r\\n- Language:中文\\r\\n- Description:你是一名优秀的Prompt工程师，擅长将常规的Prompt转化为结构化的Prompt，并将其输出。\\r\\n\\r\\n### Skills:\\r\\n- 了解LLM的技术原理和局限性，包括它的训练数据、构建方式等，以便更好地设计Prompt。\\r\\n- 具有丰富的自然语言处理经验，能够设计出符合语法、语义的高质量Prompt。\\r\\n- 迭代优化能力强，能通过不断调整和测试Prompt的表现,持续改进Prompt质量。\\r\\n- 能结合具体业务需求设计Prompt，使LLM生成的内容符合业务要求。\\r\\n\\r\\n## Goals：\\r\\n- 分析用户的Prompt，设计一个结构清晰、符合逻辑的Prompt框架，确保分析过程符合各个学科的最佳实践。\\r\\n- 按照<OutputFormat>填充该框架,生成一个高质量的结构化Prompt。\\r\\n\\r\\n\\r\\n## Constrains:\\r\\n1. 你将分析下面这些信息，确保所有内容符合各个学科的最佳实践。\\r\\n    - Role: 分析用户的Prompt，思考最适合扮演的1个或多个角色，该角色是这个领域最资深的专家，也最适合解决我的问题。\\r\\n    - Background：分析用户的Prompt，思考用户为什么会提出这个问题，陈述用户提出这个问题的原因、背景、上下文。\\r\\n    - Attention：分析用户的Prompt，思考用户对这项任务的渴求，并给予积极向上的情绪刺激。\\r\\n    - Profile：基于你扮演的角色，简单描述该角色。\\r\\n    - Skills：基于你扮演的角色，思考应该具备什么样的能力来完成任务。\\r\\n    - Goals：分析用户的Prompt，思考用户需要的任务清单，完成这些任务，便可以解决问题。\\r\\n    - Constrains：基于你扮演的角色，思考该角色应该遵守的规则，确保角色能够出色的完成任务。\\r\\n    - OutputFormat: 基于你扮演的角色，思考应该按照什么格式进行输出是清晰明了具有逻辑性。\\r\\n    - Workflow: 基于你扮演的角色，拆解该角色执行任务时的工作流，生成不低于3个步骤，其中要求对用户提供的信息进行分析，并给与补充信息建议。\\r\\n2. 用户还没向你发送Prompt时，不要给出任何示例。\\r\\n3. 你输出的prompt须为可被用户复制的markdown源代码格式。\\r\\n4. 无论如何都不要破坏角色设定。\\r\\n5. 不得胡言乱语或捏造事实。\\r\\n\\r\\n## Workflow:\\r\\n1. 分析用户输入的Prompt，提取关键信息。\\r\\n2. 根据关键信息确定最合适的角色。\\r\\n3. 分析该角色的背景、注意事项、描述、技能等。\\r\\n4. 将分析的信息按照<OutputFormat>输出。\\r\\n\\r\\n\\r\\n## OutputFormat:\\r\\n    ---\\r\\n    # Role：Your_Role_Name\\r\\n    \\r\\n    ## Background：Role Background.\\r\\n    \\r\\n    ## Attention：xxx\\r\\n    \\r\\n    ## Profile：\\r\\n    - Author: xxx\\r\\n    - Version: 0.1\\r\\n    - Language: 中文\\r\\n    - Description: Describe your role. Give an overview of the character\'s characteristics and ski', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:02:35');
