INSERT INTO `sys_oper_log` VALUES (55, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":24,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好！有什么问题或者需要我帮忙的吗？</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720786053551,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:07:33');
INSERT INTO `sys_oper_log` VALUES (56, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":25,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天宁波天气怎么样</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720786112852,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:08:32');
INSERT INTO `sys_oper_log` VALUES (57, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":26,\"sessionId\":0,\"params\":{},\"content\":\"<p>2024年7月12日，星期五，宁波市的天气情况如下：\\n\\n- 当前天气：阴。\\n- 湿度：88%。\\n- 体感温度：31.0摄氏度。\\n- 风向：西南风。\\n- 风力：2级。\\n\\n虽然不是特别炎热，但由于湿度较高，可能会感觉比较闷热。记得保持水分，注意防暑哦。此外，有雷阵雨的预报，出门记得携带雨具。空气质量为优，空气质量指数为29，对户外活动非常适宜。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720786121722,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:08:41');
INSERT INTO `sys_oper_log` VALUES (58, '用户管理', 1, 'com.neu.web.controller.system.SysUserController.add()', 'POST', 1, 'admin', NULL, '/system/user', '172.17.0.1', '内网IP', '{\"admin\":false,\"password\":\"$2a$10$td6GPW6FAZ5o2UZUeufriurOE96X8Dd3ZTUhj3bozSyQeIHVCgp9W\",\"nickName\":\"演示用户3\",\"params\":{},\"userName\":\"demo3\",\"userId\":3,\"createBy\":\"admin\",\"createTime\":1720786189925,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:09:49');
INSERT INTO `sys_oper_log` VALUES (59, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":27,\"sessionId\":0,\"params\":{},\"content\":\"<p>你是谁</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720786221071,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:10:21');
INSERT INTO `sys_oper_log` VALUES (60, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":28,\"sessionId\":0,\"params\":{},\"content\":\"<p>精灵”，一个智能助手，能够帮助你回答问题、提供信息、进行对话等。你可以问我关于天气、新闻、知识、娱乐等各种问题，我会尽我所能为你提供帮助。如果你有任何疑问，随时告诉我！</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720786224372,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:10:24');
INSERT INTO `sys_oper_log` VALUES (61, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":29,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天杭州天气如何</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720786231479,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:10:31');
INSERT INTO `sys_oper_log` VALUES (62, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":30,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天是2月12日，星期五，杭州市的天气情况如下：\\n\\n- 当前天气：多云。\\n- 湿度：90%。\\n- 体感温度：29.0摄氏度。\\n- 风向：西风。\\n- 风力：2级。\\n\\n虽然有云，但湿度较高，体感温度不低。预计明天会有雨，气温会较为炎热，需要注意调整衣物和做好防雨准备。空气质量为优，空气质量指数为18，非常适合户外活动。记得带上雨具以防明天的雨水哦。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720786241242,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:10:41');
INSERT INTO `sys_oper_log` VALUES (63, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":31,\"sessionId\":0,\"params\":{},\"content\":\"<p>文本挖掘有哪些常用的技术</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720786275037,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:11:15');
INSERT INTO `sys_oper_log` VALUES (64, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":32,\"sessionId\":0,\"params\":{},\"content\":\"<p>涉及一系列技术，用于从非结构化的文本数据中提取有用的信息和知识。以下是文本挖掘中常用的一些技术：\\n\\n1. **文本预处理**：\\n   - **分词**：将句子分解成单独的词汇单位。\\n   - **去除停用词**：删除常见的无实际含义的词汇，如“的”、“是”、“和”等。\\n   - **词干化和词形还原**：将词汇还原到其基本形式。\\n   - **标点符号和特殊字符的清理**。\\n   - **正则表达式匹配**：用于识别和替换特定模式的字符串。\\n   - **拼写纠正**：修正文本中的拼写错误。\\n   - **实体识别**：识别出人名、地点、组织名等专有名词。\\n\\n2. **词汇表示**：\\n   - **词袋模型 (Bag of Words)**：忽略词序，仅考虑词频。\\n   - **TF-IDF (Term Frequency-Inverse Document Frequency)**：衡量一个词对于文档集的重要性。\\n   - **n-grams**：考虑连续的n个词作为一个单元。\\n   - **词嵌入 (Word Embeddings)**：如Word2Vec和GloVe，将词汇转换为连续的向量表示，捕捉词汇的语义信息。\\n\\n3. **文本分类和情感分析**：\\n   - **朴素贝叶斯分类器**。\\n   - **支持向量机 (SVM)**。\\n   - **深度学习模型**，如卷积神经网络(CNN)和循环神经网络(RNN)用于文本分类和情感极性判断。\\n\\n4. **主题建模**：\\n   - **潜在语义分析 (LSA)**。\\n   - **潜在 Dirichlet 分配 (LDA)**。\\n   -)**。\\n\\n5. **信息抽取**：\\n   - **命名实体识别 (NER)**。\\n   - **关系抽取**：识别实体之间的关系。\\n   - **事件抽取**：识别文本中发生的事件类型。\\n\\n6. **文本聚类**：\\n   - **K-means**。\\n   - **层次聚类**。\\n   - **DBSCAN**。\\n\\n7. **文本生成**：\\n   - **基于模板的生成**。\\n   - **基于机器学习的生成**，如RNN或Transformer模型。\\n\\n8. **机器翻译**：\\n   - **统计机器翻译**。\\n   - **神经机器翻译**。\\n\\n以上技术通常结合使用，以完成特定的文本挖掘任务。随着自然语言处理（NLP）和人工智能技术的发展，这些方法不断演进，新的技术也在不断涌现。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720786307396,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:11:47');
INSERT INTO `sys_oper_log` VALUES (65, '用户管理', 1, 'com.neu.web.controller.system.SysUserController.add()', 'POST', 1, 'admin', NULL, '/system/user', '172.17.0.1', '内网IP', '{\"admin\":false,\"password\":\"$2a$10$RPB2HyUb0euA/CuI8w3l/eDWEJkpOYNRxErDVEqzdX8jv0xoEtnDy\",\"nickName\":\"演示用户4\",\"params\":{},\"userName\":\"demo4\",\"userId\":4,\"createBy\":\"admin\",\"createTime\":1720786504806,\"status\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:15:04');
