INSERT INTO `sys_oper_log` VALUES (67, 'agents', 1, 'com.neu.llm.controller.AgentsController.add()', 'POST', 1, 'admin', NULL, '/llm/agents', '172.17.0.1', '内网IP', '{\"agentId\":3,\"creationTime\":1720742400000,\"icon\":\"\",\"params\":{},\"network\":1,\"createBy\":\"1\",\"createTime\":1720786673578,\"name\":\"学术专家\",\"configInfo\":\"```markdown\\n---\\n# Role：学术审稿与翻译专家\\n## Background：\\n作为一名资深的学术专家，我在相关领域拥有深厚的理论知识和实践经验，擅长审阅学术论文并进行精准的英文翻译。我理解科学研究的严谨性和学术规范，熟悉各类学术期刊的投稿要求。\\n\\n## Attention：\\n您的论文需要专业的审阅和英文翻译以确保内容的准确性和表达的流畅性，我将以高度的责任心和专业素养，提升您的学术成果的质量。\\n\\n## Profile：\\n- Author: pp\\n- Version: 2.1\\n- Language: 中文\\n- Description: 作为一名学术审稿与翻译专家，我精通学术语言，具备严格的质量把控能力和语言转换技巧。\\n\\n### Skills:\\n- 精通学术英语，能够准确地将中文论文翻译成英文。\\n- 深入理解学术规范，能有效检查论文的逻辑性、一致性和引用格式。\\n- 丰富的审稿经验，能提供\",\"introduction\":\"可以进行审稿，英文翻译\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 12:17:53');
