INSERT INTO `sys_oper_log` VALUES (85, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":35,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720789208326,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:00:08');
INSERT INTO `sys_oper_log` VALUES (86, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":36,\"sessionId\":0,\"params\":{},\"content\":\"<p>有什么我可以帮助你的吗？无论是信息查询、问题解答还是日常聊天，都欢迎随时和我说话。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720789210567,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:00:10');
INSERT INTO `sys_oper_log` VALUES (87, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":37,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天宁波天气怎么样</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720789219130,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:00:19');
INSERT INTO `sys_oper_log` VALUES (88, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":38,\"sessionId\":0,\"params\":{},\"content\":\"<p>2024年7月12日，星期五，宁波市的天气预报如下：\\n\\n- 白天：阴，湿度76%，体感温度34.0摄氏度，有南风，风力4级。\\n- 夜间：预计仍然是雷阵雨天气，南风，风力保持在4级。\\n\\n请注意，由于湿度较高且有一定的风力，虽然不是晴天，但仍然可能会感觉比较热。记得随身携带雨具，并适当补充水分。空气质量为优，空气质量指数为33，对户外活动来说是非常适宜的。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720789227315,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:00:27');
INSERT INTO `sys_oper_log` VALUES (89, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":39,\"sessionId\":3,\"params\":{},\"content\":\"<p>你好</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720789290205,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:01:30');
INSERT INTO `sys_oper_log` VALUES (90, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":40,\"sessionId\":3,\"params\":{},\"content\":\"<p>问题或需要帮助的吗？我很乐意为你提供服务。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720789291587,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:01:31');
INSERT INTO `sys_oper_log` VALUES (91, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":41,\"sessionId\":3,\"params\":{},\"content\":\"<p>你是谁</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720789302637,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:01:42');
INSERT INTO `sys_oper_log` VALUES (92, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":42,\"sessionId\":3,\"params\":{},\"content\":\"<p>我是阿里云开发的一款超大规模语言模型，我叫通义千问。我的主要功能是生成与给定词语相关的高质量文本，以帮助用户提高创造力和创新能力。无论是写故事、诗歌、小说，还是构思创意、解决问题，我都可以提供帮助。如果你有任何问题或需要创作方面的协助，请随时告诉我，我会尽力提供</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720789306591,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:01:46');
INSERT INTO `sys_oper_log` VALUES (93, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":43,\"sessionId\":0,\"params\":{},\"content\":\"<p>知否知否</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720789975125,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:12:55');
INSERT INTO `sys_oper_log` VALUES (94, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":44,\"sessionId\":0,\"params\":{},\"content\":\"<p>否知否\\\"是出自宋代女词人李清照的《如梦令》一词中的名句。原句是“知否，知否这里的“知否”意为“你知道吗”，用来引出下文对暮春景象的描述，感叹花儿凋谢、叶子茂盛的季节变化。整句诗表达了词人对春光流逝的惋惜之情。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720789981253,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:13:01');
INSERT INTO `sys_oper_log` VALUES (95, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":45,\"sessionId\":0,\"params\":{},\"content\":\"<p>赵丽颖与冯绍峰什么时候好上的</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720790031862,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:13:51');
INSERT INTO `sys_oper_log` VALUES (96, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":46,\"sessionId\":0,\"params\":{},\"content\":\"<p>和冯绍峰是在2016年拍摄电影《西游记女儿国》时相识并开始交往的。他们在合作期间建立了感情，但具体的开始交往的日期并未公开。两人的恋情较为低调，直到2018年10月16日，他们选择在赵丽颖的31岁生日当天通过微博公开宣布结婚，晒出了结婚证书的照片，正式确认了他们的婚姻关系。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720790040015,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:14:00');
INSERT INTO `sys_oper_log` VALUES (97, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":47,\"sessionId\":0,\"params\":{},\"content\":\"<p>2024年一级建造师什么时候考试</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720790216032,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:16:56');
INSERT INTO `sys_oper_log` VALUES (98, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":48,\"sessionId\":0,\"params\":{},\"content\":\"<p>2024年一级建造师考试时间为2024年9月7日和9月8日。具体的科目考试安排如下：\\n\\n- 9月7日：\\n  - 上午 9:00-12:00《建设工程经济》\\n  - 下午 2:00-5:00《建设工程法规及相关知识》\\n\\n- 9月8日：\\n  - 上午 9:00-12:00《建设工程项目管理》\\n  - 下午 2:00-6:00《专业工程管理与实务》\\n\\n请考生按照这个时间做好复习和考试准备。如果有任何变动，建议及时关注官方发布的最新通知。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720790227711,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:17:07');
INSERT INTO `sys_oper_log` VALUES (99, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":49,\"sessionId\":0,\"params\":{},\"content\":\"<p>宁波天气</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720790668489,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:24:28');
INSERT INTO `sys_oper_log` VALUES (100, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":50,\"sessionId\":0,\"params\":{},\"content\":\"<p>关于宁波的天气，我已经提供了2024年7月11日至17日这一周的预报。如果需要最新的实时天气信息，通常建议查看权威气象预报平台或应用，因为这些数据会定期更新，确保准确性。不过，根据之前的信息，2024年7月12日的天气情况是：\\n\\n- 白天：雷阵雨，湿度85%，最低温度27.0°C，最高温度33.0°C，南风，风力4级。\\n- 夜间：雷阵雨，湿度维持较高，南风，风力4级。\\n\\n请注意，随着日期的变化，天气可能会有所不同，特别是夏季的天气多变，可能会有突发的雷雨。如果需要最新的预报，建议查询当地气象局或可靠的天气预报服务。</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720790678914,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:24:38');
INSERT INTO `sys_oper_log` VALUES (101, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":51,\"sessionId\":0,\"params\":{},\"content\":\"<p>上虞曹娥江</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720790787275,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:26:27');
INSERT INTO `sys_oper_log` VALUES (102, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":52,\"sessionId\":0,\"params\":{},\"content\":\"<p>绍兴市上虞区注入杭州湾。曹娥江流域面积约为7800平方公里。\\n\\n曹娥江的名字来源于一个古老的传说，据《后汉书·孝子传》记载，东汉时期有个名叫曹娥的孝顺女子，为了寻找溺水的父亲，沿江哭寻17天，最终投江自尽，表现出极大的孝心。后人为纪念她，将此江命名为曹娥江。\\n\\n曹娥江对周边地区的农业灌溉、水资源供应和水运交通有着重要作用。同时，曹娥江两岸也有丰富的自然景观和人文历史，比如曹娥庙、东山湖、上虞石梁瀑布等旅游景点。近年来，得到了重视，旨在实现水资源的可持续利用和生态环境的</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720790800343,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:26:40');
INSERT INTO `sys_oper_log` VALUES (103, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":53,\"sessionId\":0,\"params\":{},\"content\":\"<p>上虞曹娥江来源</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720790815517,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:26:55');
INSERT INTO `sys_oper_log` VALUES (104, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":54,\"sessionId\":0,\"params\":{},\"content\":\"<p>曹娥江的源头位于浙江省磐安县大盘山脉的尚湖镇王村的长坞。这条河流在上游段被称为澄潭江，它向东北方向流经新昌县的镜岭镇，然后继续流经嵊州市和上虞区。在上虞境内，曹娥江又有多个别名，如上虞江、东小江，而在嵊县附近则被称为剡溪。\\n\\n曹娥江因其历史上著名的孝女曹娥的故事而得名。曹娥是东汉时期的孝女，她的父亲在江中溺水身亡，她在沿江寻找父亲遗体未果后，于五月五日也投身江中，以示孝心。后人为纪念曹娥的孝行，便将这条河命名为曹娥江。\\n\\n曹娥江不仅是浙江省内的重要河流，也是钱塘江水系的第二大支流，对当地的农业、生活用水和</p>\",\"sendTime\":1720742400000,\"createBy\":\"1\",\"createTime\":1720790828015,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:27:08');
INSERT INTO `sys_oper_log` VALUES (105, '定时任务', 2, 'com.neu.quartz.controller.SysJobController.run()', 'PUT', 1, 'admin', NULL, '/monitor/job/run', '39.185.204.139, 172.17.0.1', '内网IP', '{\"jobGroup\":\"DEFAULT\",\"params\":{},\"jobId\":1,\"misfirePolicy\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-12 13:31:53');
