INSERT INTO `sys_oper_log` VALUES (107, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":55,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天杭州天气怎么样</p>\",\"sendTime\":1720828800000,\"createBy\":\"1\",\"createTime\":1720840467563,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-13 03:14:27');
INSERT INTO `sys_oper_log` VALUES (108, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":56,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天杭州天气怎么样</p>\",\"sendTime\":1720828800000,\"createBy\":\"1\",\"createTime\":1720840570939,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-13 03:16:10');
INSERT INTO `sys_oper_log` VALUES (109, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":57,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天是2024年7月13日，星期六，杭州市的天气预报如下：\\n\\n- 白天有雷阵雨，湿度为84%，最低温度26.0摄氏度，最高温度34.0摄氏度，吹的是西南风，风力4级。\\n- 夜间天气转为多云，西风，风力降为3级。\\n\\n由于湿度较高且气温不低，记得外出时携带雨具，并注意防暑降温，保持水分。空气质量和前一天一样，依然保持在优的状态，空气质量指数为26。</p>\",\"sendTime\":1720828800000,\"createBy\":\"1\",\"createTime\":1720840579096,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-13 03:16:19');
INSERT INTO `sys_oper_log` VALUES (110, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":58,\"sessionId\":0,\"params\":{},\"content\":\"<p>1111</p>\",\"sendTime\":1720828800000,\"createBy\":\"1\",\"createTime\":1720841360129,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-13 03:29:20');
