INSERT INTO `sys_oper_log` VALUES (131, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":65,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好有什么我可以为你做的吗？无论是聊天、分享快乐、还是帮助你解决困扰，我都愿意在这里陪伴你。</p>\",\"sendTime\":1720828800000,\"createBy\":\"1\",\"createTime\":1720875913990,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-13 13:05:14');
INSERT INTO `sys_oper_log` VALUES (132, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":66,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好</p>\",\"sendTime\":1720828800000,\"createBy\":\"1\",\"createTime\":1720876992129,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-13 13:23:12');
INSERT INTO `sys_oper_log` VALUES (133, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":67,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好！有什么可以帮到你的吗？如果你需要聊天、寻求建议或者只是想要一个倾听者，我都在这里。</p>\",\"sendTime\":1720828800000,\"createBy\":\"1\",\"createTime\":1720876994157,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-13 13:23:14');
INSERT INTO `sys_oper_log` VALUES (134, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":68,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天宁波的天气如何</p>\",\"sendTime\":1720828800000,\"createBy\":\"1\",\"createTime\":1720877003126,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-13 13:23:23');
INSERT INTO `sys_oper_log` VALUES (135, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":69,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天是2024年7月13日，星期六，宁波市的天气预报如下：\\n\\n- 白天：阴天，湿度83%，最低温度26.0摄氏度，最高温度34.0摄氏度，有雷阵雨，南风，风力4级。\\n- 夜间：天气转为多云，南风持续，风力4级。\\n\\n由于湿度较高，体感温度可能会比实际气温更高，注意防暑和避免长时间暴露在户外。此外，虽然空气质量良好，但雷阵雨天气出门记得携带雨具，并注意安全。</p>\",\"sendTime\":1720828800000,\"createBy\":\"1\",\"createTime\":1720877012081,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-13 13:23:32');
