INSERT INTO `sys_oper_log` VALUES (143, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":70,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720920917315,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 01:35:17');
INSERT INTO `sys_oper_log` VALUES (144, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":71,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好！有什么可以帮到你的吗？无论是日常的问答，还是需要情感上的支持，我都愿意为你提供帮助。</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720920919473,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 01:35:19');
INSERT INTO `sys_oper_log` VALUES (145, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":72,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720920936351,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 01:35:36');
INSERT INTO `sys_oper_log` VALUES (146, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":73,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好可以为你做的吗？如果你有任何问题或者想要聊聊天，我都在这里。</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720920938299,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 01:35:38');
INSERT INTO `sys_oper_log` VALUES (147, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":74,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天吃了什么</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720923778442,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 02:22:58');
INSERT INTO `sys_oper_log` VALUES (148, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":75,\"sessionId\":0,\"params\":{},\"content\":\"<p>作为一个我没有能力吃饭或体验口感，所以我没有“吃”的概念。不过，我很想知道你今天吃了什么呢？或许我们可以聊聊关于食物的话题，分享一下你喜欢的菜肴或者饮食习惯。</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720923781320,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 02:23:01');
INSERT INTO `sys_oper_log` VALUES (149, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":76,\"sessionId\":0,\"params\":{},\"content\":\"<p>你是谁</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720923954662,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 02:25:54');
INSERT INTO `sys_oper_log` VALUES (150, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":77,\"sessionId\":0,\"params\":{},\"content\":\"<p>我是，一个智能助手，专门设计来帮助你解决问题、提供信息、进行对话以及在你需要的时候给予情感支持。你可以问我任何问题，或者和我分享你的想法和感受。</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720923957856,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 02:25:57');
INSERT INTO `sys_oper_log` VALUES (151, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":78,\"sessionId\":0,\"params\":{},\"content\":\"<p>我刚刚说了什么</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720923963551,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 02:26:03');
INSERT INTO `sys_oper_log` VALUES (152, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":79,\"sessionId\":0,\"params\":{},\"content\":\"<p>你刚刚问了：“你是谁？”我回答了你是情感精灵，一个智能助手，旨在为你提供帮助和服务。</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720923965885,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 02:26:05');
INSERT INTO `sys_oper_log` VALUES (153, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":80,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720926060398,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 03:01:00');
INSERT INTO `sys_oper_log` VALUES (154, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":81,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好！有什么问题或需要帮助吗？我在这里可以提供数学作业解答、科普知识、日常建议等各种帮助</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720926062327,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 03:01:02');
INSERT INTO `sys_oper_log` VALUES (155, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":82,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天宁波天气怎么样</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720926588182,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 03:09:48');
INSERT INTO `sys_oper_log` VALUES (156, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":83,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天是2024年7月14日，星期日，根据之前提供的信息，宁波市的天气情况如下：\\n\\n- 当前天气：阴。\\n- 湿度：90%\\n- 最低温度：27.0摄氏度\\n- 最高温度：34.0摄氏度\\n- 白天天气：雷阵雨\\n- 风向：南风\\n- 风力：4级\\n\\n记得由于天气较热且有雨，外出时带上雨具，注意防暑并适当补水。空气质量和能见度方面应该都是较好的。</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720926595390,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 03:09:55');
