INSERT INTO `sys_oper_log` VALUES (158, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":85,\"sessionId\":0,\"params\":{},\"content\":\"<p>您刚刚询问了关于宁波今天的天气情况。我告诉了您今天宁波的天气预报，包括天气状况、湿度、温度范围以及有雷阵雨的可能性，并给出了相应的出行建议。</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720926627613,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 03:10:27');
