INSERT INTO `sys_oper_log` VALUES (163, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":90,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好有什么我可以为你做的吗？无论是聊天、分享快乐还是帮助你解决困扰，我都在这里。</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720936112482,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 05:48:32');
INSERT INTO `sys_oper_log` VALUES (164, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":91,\"sessionId\":0,\"params\":{},\"content\":\"<p>明天杭州天气怎么样？</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720936173462,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 05:49:33');
INSERT INTO `sys_oper_log` VALUES (165, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":92,\"sessionId\":0,\"params\":{},\"content\":\"<p>明天是2024年7月15日，杭州市的天气预报如下：\\n\\n- 湿度85%，最低温度27.0摄氏度，最高温度36.0摄氏度。\\n- 白天天气晴朗，有南风，风力为3级。\\n- 夜间天气依然晴朗，南风持续，风力增加到4级。\\n\\n记得在这样炎热的天气里做好防晒措施，保持水分，避免中暑。如果有户外活动，尽量选择早晨或傍晚较为凉爽的时候。</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720936181680,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 05:49:41');
