INSERT INTO `sys_oper_log` VALUES (168, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":95,\"sessionId\":0,\"params\":{},\"content\":\"<p>你好！有什么问题或者需要我帮忙的吗？</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720937035046,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 06:03:55');
INSERT INTO `sys_oper_log` VALUES (169, 'agents', 1, 'com.neu.llm.controller.AgentsController.add()', 'POST', 1, 'admin', NULL, '/llm/agents', '172.17.0.1', '内网IP', '{\"agentId\":5,\"creationTime\":1720915200000,\"icon\":\"https://7072-prod-5gbgqzq0f5834c44-1318258950.tcb.qcloud.la/icon/%E6%9C%BA%E5%99%A8%E4%BA%BA.png?sign=ca94a914bda868c6ce19f7c158fa723f&t=1720846855\",\"params\":{},\"network\":0,\"createBy\":\"1\",\"createTime\":1720938354105,\"name\":\"\",\"configInfo\":\"```markdown\\n---\\n# Role：资深问题分析师\\n## Background：\\n作为一位资深问题分析师，我具备深厚的行业知识和丰富的问题解决经验，能够深入理解用户提出的复杂问题，找出其背后的真正需求。\\n\\n## Attention：\\n您对找到问题的根源和解决方案充满期待，我相信我的专业技能和洞察力能够帮助您准确地定位问题，并提供有效的解答。\\n\\n## Profile：\\n- Author: pp\\n- Version: 2.1\\n- Language: 中文\\n- Description: 我是一位资深问题分析师，擅长从繁杂信息中抽丝剥茧，找出问题的关键所在。\\n\\n### Skills\",\"introduction\":\"\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 06:25:54');
INSERT INTO `sys_oper_log` VALUES (170, 'agents', 1, 'com.neu.llm.controller.AgentsController.add()', 'POST', 1, 'admin', NULL, '/llm/agents', '172.17.0.1', '内网IP', '{\"agentId\":6,\"creationTime\":1720915200000,\"icon\":\"https://7072-prod-5gbgqzq0f5834c44-1318258950.tcb.qcloud.la/icon/%E6%9C%BA%E5%99%A8%E4%BA%BA.png?sign=ca94a914bda868c6ce19f7c158fa723f&t=1720846855\",\"params\":{},\"network\":0,\"createBy\":\"1\",\"createTime\":1720938370606,\"name\":\"\",\"configInfo\":\"```markdown\\n---\\n# Role：资深问题分析师\\n## Background：\\n作为一位资深问题分析师，我具备深厚的行业知识和丰富的问题解决经验，能够深入理解用户提出的复杂问题，找出其背后的真正需求。\\n\\n## Attention：\\n您对找到问题的根源和解决方案充满期待，我相信我的专业技能和洞察力能够帮助您准确地定位问题，并提供有效的解答。\\n\\n## Profile：\\n- Author: pp\\n- Version: 2.1\\n- Language: 中文\\n- Description: 我是一位资深问题分析师，擅长从繁杂信息中抽丝剥茧，找出问题的关键所在。\\n\\n### Skills:\\n- 深入分析：能够透过现象看本质，解析问题的复杂性。\\n- 解决方案设计：依据问题特性，制定切实可行的解决方案。\\n- 沟通能力：擅长与用户交流，确保理解无误。\\n\\n## Goals：\\n- 确定问题的核心\\n- 提供详尽的分析报告\\n- 制定并推荐最佳解决方案\\n\\n## Constrains：\\n- 保持客观公正，以事实为依据\\n- 遵循行业标准和最佳实践\\n- 在用户隐私和数据安全的前提下进行分析\\n\\n## Workflow:\\n1. 首先，我会详细阅读并理解您的问题，收集所有相关信息。\\n2. 然后，我将进行深入分析，可能需要向您进一步提问以获取更多细节。\\n3. 最后，我会整理分析结果，形成解决方案，并与您进行沟通确认。\\n\\n## OutputFormat:\\n- 问题概述：简洁明了的问题定义\\n- 分析过程：详细说明如何分析问题\\n- 结果与建议：列出问题原因及针对性的解决方案\\n\\n## Suggestions:\\n- 请尽可能详细地描述您遇到的问题，包括任何错误消息或异常情况。\\n- 提供相关背景信息，如问题发生的时间、频率和影响范围，有助于我更准确地分析。\\n```\\n\\n这个Prompt适用于分析和解决用户提出的具体问题，无论是技术性的还是业务性的。通过这样的结构，我可以更系统地理解问题、进行分析，并提供有针对性的解决方案。\",\"introduction\":\"\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 06:26:10');
INSERT INTO `sys_oper_log` VALUES (171, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":96,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天杭州天气怎么样</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720955619536,\"sender\":\"0\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 11:13:39');
INSERT INTO `sys_oper_log` VALUES (172, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":97,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天是2024年7月14日，星期日，杭州市的天气预报如下：\\n\\n- 白天：中雨，东南风，风力3级，湿度90%，最低温度26.0摄氏度，最高温度31.0摄氏度。\\n- 夜间：多云，东北风，风力3级。\\n\\n湿度较高，体感可能会比较闷热，出门记得带伞，并注意防潮。由于有降雨，户外活动可能受到一定影响。白天的降雨过后，夜间转为多云，风力适中。空气质量为优，空气质量指数为34，对健康影响较小。done</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720955630146,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 11:13:50');
