INSERT INTO `sys_oper_log` VALUES (175, 'message', 1, 'com.neu.llm.controller.MessageController.add()', 'POST', 1, 'admin', NULL, '/llm/message', '172.17.0.1', '内网IP', '{\"messageId\":99,\"sessionId\":0,\"params\":{},\"content\":\"<p>今天是2024年7月14日，杭州市的天气情况如下：\\n- 白天：中雨，湿度90%，最高温度31.0摄氏度，东南风，风力3级。\\n- 夜间：晴朗，湿度未给出，最低温度25.0摄氏度，东北风，风力3级。\\n\\n体感温度较高，建议注意防雨和适当补水。空气质量为优，空气质量指数为34，适合户外活动。</p>\",\"sendTime\":1720915200000,\"createBy\":\"1\",\"createTime\":1720956936789,\"sender\":\"1\"}', '{\"msg\":\"操作成功\",\"code\":200}', 0, NULL, '2024-07-14 11:35:36');
