INSERT INTO `video` VALUES (4, 'https://www.bilibili.com/video/BV1yG41127kh/', '快速傅里叶变换(FFT)——有史以来最巧妙的算法？| 双字解析/变换解析资源/人工智能！', '<p><span style=\"color: rgb(24, 25, 28);\">快速傅里叶变换（FFT）是一种计算离散傅里叶变换（DFT）及其逆变换的高效、快速算法的统称。</span></p>', 'http://i2.hdslb.com/bfs/archive/c64ae17d16fb16bcd49557a7fbf24e7122ff4167.png', 'https://player.bilibili.com/player.html?aid=407314919&cid=1304370017&page=1');
